cd /workspace/SuperGrok1.5 && for tag in tune_base tune_2944 tune_7a88 tune_aba7; do
  case $tag in
    tune_base) f=tune11_out/grokking_compiled_adamw_decoder_sm_90a/grokking_compiled_adamw_decoder_sm_90a.so;;
    tune_2944) f=tune11_out/grokking_compiled_adamw_decoder_sm_90a_2944e03f7cd60f3e/grokking_compiled_adamw_decoder_sm_90a_2944e03f7cd60f3e.so;;
    tune_7a88) f=tune11_out/grokking_compiled_adamw_decoder_sm_90a_7a882d5329a20564/grokking_compiled_adamw_decoder_sm_90a_7a882d5329a20564.so;;
    tune_aba7) f=tune11_out/grokking_compiled_adamw_decoder_sm_90a_aba71f216d321649/grokking_compiled_adamw_decoder_sm_90a_aba71f216d321649.so;;
  esac
  echo "############ $tag ############"
  cuobjdump --dump-resource-usage "$f" 2>/dev/null > /workspace/phase0c/res_${tag}.txt
  # Decoder OptId 10 (the production AdamW path is OptId encoding) - just show all decoder functions REG/STACK/SHARED
  echo "--- DECODER functions (REG/STACK/SHARED) ---"
  grep -A1 "fused_decoder_megakernel_tc" /workspace/phase0c/res_${tag}.txt | grep -E "OptIdE|REG:" | paste - - | sed -E 's/.*OptIdE([0-9]+)EE.*REG:([0-9]+) STACK:([0-9]+) SHARED:([0-9]+).*/OptId\1  REG=\2 STACK=\3 SHARED=\4/' | head -20
done

